import {askConfirm,enhanceSelects,closeDialog} from './dialogs.js';
import {learningHTML} from './learning.js';
import {esc,icon,toast,duration,date,debounce} from './utils.js';
import {catalog,loadQuestions,filterQuestions} from './question-loader.js';
import {readState,persist,defaults,validateData} from './storage.js';
import {createSession,recordAnswer,score,statistics} from './quiz-engine.js';
import {codeBlock} from './code-renderer.js';
import {navigate,route} from './router.js';
import {applySettings,playFeedback} from './theme.js';
import {searchCollections,searchQuestions} from './search.js';
const $=s=>document.querySelector(s),main=$('#main');
let allLoaded=false;
let state=await readState(),all=[],currentQuestions=[],config=null,matching=[],selection=[],hint=false,viewedResult=null,timer=null,lastTick=Date.now(),renderToken=0;
const formatNames={mcq:'Multiple choice',output:'Predict the output',bug:'Find the bug',complete:'Complete the code',syntax:'Correct syntax',concept:'Concept check',boolean:'True / False',multiple:'Multiple answers',comparison:'Compare code',debug:'Debugging scenario',interview:'Interview question'};
const total=catalog.reduce((n,c)=>n+c.count,0);
applySettings(state.settings);
async function save(){try{await persist(state);return true}catch(e){toast(e.message);return false}}
async function getAll(){if(!allLoaded){all=await loadQuestions();allLoaded=true}return all}
async function loadForSession(s){const banks=catalog.filter(c=>s.ids.some(id=>id.startsWith(c.id+'-')));const loaded=(await Promise.all(banks.map(c=>loadQuestions(c.id)))).flat();all=[...new Map([...all,...loaded].map(q=>[q.id,q])).values()]}
const navItems=[['/','home','Home'],['/explore','explore','Explore'],['/bookmarks','bookmark','Bookmarks'],['/settings','settings','Settings']];
function chrome(){const path=route();const active=p=>p==='/'?path==='/':path.startsWith(p);$('#sidebar').innerHTML=`<a href="#/" class="brand"><span class="brand-mark">&lt;/&gt;</span>CodeQuest<em>.</em></a><div class="side-group"><div class="eyebrow">Workspace</div>${navItems.slice(0,3).map(([p,i,t])=>`<a class="side-link ${active(p)?'active':''}" href="#${p}">${icon(i)}${t}${p==='/bookmarks'?`<span class="count">${state.bookmarks.length}</span>`:''}</a>`).join('')}<a class="side-link ${path==='/history'?'active':''}" href="#/history">${icon('history')}Quiz history</a></div><a class="side-link ${path.startsWith('/learn')?'active':''}" href="#/learn">${icon('bulb')}Beginner paths</a><div class="side-group"><div class="eyebrow">Practice your way</div><a class="side-link" href="#/config/all?pool=incorrect">${icon('refresh')}Revisit mistakes</a><a class="side-link" href="#/config/all?timed=1">${icon('clock')}Time challenge</a><a class="side-link" href="#/config/all">${icon('layers')}Custom quiz</a></div><div class="sidebar-bottom"><a class="side-link ${active('/settings')?'active':''}" href="#/settings">${icon('settings')}Settings</a><div class="local-label">${icon('shield')}<div><strong>Just you and your code.</strong>Local progress. No account.</div></div><small style="display:block;margin:15px 10px 0;font-size:10px">CODEQUEST &nbsp; / &nbsp; V2.0</small></div>`;
 $('#bottomnav').innerHTML=navItems.map(([p,i,t])=>`<a href="#${p}" class="${active(p)?'active':''}" ${active(p)?'aria-current="page"':''}>${icon(i)}${t}</a>`).join('');
 const name=path==='/'?'Overview':path.startsWith('/quiz')?'Practice session':path.startsWith('/config')?'Set up your quiz':path.startsWith('/results')?'Session results':path.slice(1).replace(/^./,c=>c.toUpperCase());
 $('#topbar').innerHTML=`<div class="breadcrumb">Workspace <span>/</span><span>${esc(name)}</span></div><a href="#/" class="brand mobile-brand"><span class="brand-mark">&lt;/&gt;</span>CodeQuest<em>.</em></a><div class="top-actions"><span class="pill" id="network"><i class="dot"></i>${navigator.onLine?'Local-first workspace':'You’re offline'}</span><a href="#/settings" class="icon-btn" aria-label="Open settings">${icon('settings')}</a><span class="avatar" aria-label="Personal workspace">CQ</span></div>`;
}
function pageHead(title,description,extra='',eyebrow='YOUR LEARNING WORKSPACE'){return `<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${description}</p></div>${extra}</div>`}
const searchBox=(id,placeholder='Search languages, topics…')=>`<label class="searchbox">${icon('search')}<input id="${id}" type="search" placeholder="${placeholder}" aria-label="${placeholder}"><kbd>/</kbd></label>`;
function collectionCard(c){return `<button class="collection" data-bank="${c.id}" aria-label="Configure ${esc(c.title)} quiz, ${c.count} questions"><div class="collection-top"><span class="lang-icon" style="--tint:${c.color}">${esc(c.symbol)}</span>${icon('arrow','arrow')}</div><h3>${esc(c.title)}</h3><p>${esc(c.description)}</p><small style="font-size:9px;margin-bottom:10px">${c.formats.length} formats · ${c.formats.map(f=>formatNames[f]).join(' / ')}</small><div class="collection-foot"><span>${c.count} questions</span><small>${esc(c.difficulties.join(' · '))}</small></div></button>`}
const empty=(i,t,d,link='',label='Explore collections')=>`<div class="empty">${icon(i)}<h2>${t}</h2><p>${d}</p>${link?`<a class="btn" href="#${link}">${label}${icon('arrow')}</a>`:''}</div>`;
function home(){const stats=statistics(state),recent=state.recent.map(id=>catalog.find(c=>c.id===id)).filter(Boolean).slice(0,3);main.innerHTML=`${pageHead('Your next line of thinking.','A little practice. A deeper understanding.',searchBox('home-search'))}<div id="home-search-results"></div><div class="dashboard"><div class="main-column"><section class="hero"><div class="hero-content"><div class="eyebrow">${icon('code')} A SPACE TO SHARPEN YOUR SKILLS</div><h2>Less scrolling.<br>More problem solving.</h2><p>Explore the ideas behind the code. One thoughtful question at a time.</p><a class="btn primary" href="#/config/all">Start a quiz ${icon('arrow')}</a><span class="hero-meta">Your pace. Your path.</span></div><div class="hero-art" aria-hidden="true"><div class="window-dots"><i></i><i></i><i></i></div><div class="art-code"><b>const</b> developer = {<br>&nbsp; curious: <span>true</span>,<br>&nbsp; learning: <span>'always'</span><br>};</div><div class="brace">{ }</div></div></section>${state.session?`<div class="history-item" style="margin-top:15px">${icon('play')}<div><strong>Pick up where you left off</strong><p>${state.session.ids.length} questions · ${Object.keys(state.session.responses).length} answered</p></div><a class="btn primary" href="#/quiz">Resume ${icon('arrow')}</a></div>`:''}<div class="stats-strip"><div class="stat">${icon('code')}<div><strong>${stats.attempts}</strong><small>Questions attempted</small></div></div><div class="stat">${icon('check')}<div><strong>${stats.attempts?Math.round(stats.correct/stats.attempts*100)+'%':'—'}</strong><small>Answer accuracy</small></div></div><div class="stat">${icon('layers')}<div><strong>${stats.sessions}</strong><small>Sessions completed</small></div></div></div>${recent.length?`<section class="section"><div class="section-head"><h2>Recently explored</h2><a href="#/explore">All collections ${icon('arrow')}</a></div><div class="collection-grid">${recent.map(collectionCard).join('')}</div></section>`:''}<section class="learn-intro"><span>${icon('bulb')}</span><div><div class="eyebrow">NEW TO CODING?</div><h2 style="margin:7px 0">Start small. Understand deeply.</h2><p>Variables, printing, loops and beyond. Pick a language and follow its foundations.</p><a href="#/learn" class="btn primary" style="margin-top:15px">Explore beginner paths ${icon('arrow')}</a></div></section><section class="section"><div class="section-head"><h2>Find your next challenge</h2><a href="#/explore">Explore all ${icon('arrow')}</a></div><div class="chips" id="home-chips">${['Popular','Languages','Web development','Computer science','Android','Developer skills'].map((g,i)=>`<button class="chip ${i===0?'active':''}" data-home-group="${g}">${g}</button>`).join('')}</div><div class="collection-grid" id="home-collections">${['javascript','python','java','cpp','sql','typescript'].map(id=>collectionCard(catalog.find(c=>c.id===id))).join('')}</div></section><section class="section"><div class="section-head"><h2>A different way to practice</h2><span class="eyebrow" style="font-size:8px">MAKE IT YOURS</span></div><div class="mode-grid"><a href="#/config/all?pool=incorrect" class="mode-card">${icon('refresh')}<div><h3>Revisit mistakes</h3><p>Turn missed answers into understanding.</p></div></a><a href="#/config/all?timed=1" class="mode-card">${icon('clock')}<div><h3>Time challenge</h3><p>Make room for focused thinking.</p></div></a><a href="#/config/all" class="mode-card">${icon('layers')}<div><h3>Build your own</h3><p>Your topics. Your difficulty. Your quiz.</p></div></a></div></section><details class="section"><summary style="font-size:13px;cursor:pointer">Practice by difficulty</summary><div class="chips" style="margin-top:15px">${['Easy','Medium','Hard','Expert'].map(d=>`<a class="chip" href="#/config/all?difficulty=${d}">${d}</a>`).join('')}</div></details></div><aside class="rail"><div class="rail-card"><h2>Your recent activity ${icon('history')}</h2><div class="empty-activity">${state.history.length?state.history.slice(0,3).map(h=>`<a class="activity-line" href="#/results/${esc(h.id)}"><span class="activity-icon">${icon('check')}</span><div><h3>${esc(catalog.find(c=>c.id===h.config.bank)?.title||'Mixed practice')}</h3><p>${score(h).correct} of ${h.ids.length} correct · ${date(h.finishedAt)}</p></div></a>`).join(''):`<div class="activity-line"><span class="activity-icon">${icon('code')}</span><div><h3>A fresh page, ready for you.</h3><p>Your completed sessions will appear here.</p></div></div><div class="activity-line"><span class="activity-icon">${icon('bookmark')}</span><div><h3>Keep the questions that matter.</h3><p>Bookmark anything to revisit it later.</p></div></div>`}</div><a class="text-btn rail-note" style="display:block" href="#/history">View quiz history ${icon('arrow')}</a></div><div class="rail-card spotlight"><div class="eyebrow">UNDER THE SURFACE</div><h3>Know what happens next?</h3><p>Explore closures, async behavior and the little details that make JavaScript click.</p><div class="mini-code"><span style="color:#7eacd1">const</span> think = () =&gt; {\n  <span style="color:#baa1dc">return</span> 'one step deeper';\n};</div><a class="btn" href="#/config/javascript?format=output">Try output questions ${icon('arrow')}</a></div><div class="note-card">${icon('shield')}<strong>Knowledge stays. Data stays local.</strong><p>No sign-in. No tracking. Just ${total} questions across ${catalog.length} carefully organized collections.</p><a href="#/settings" class="text-btn">Manage your local data ${icon('arrow')}</a></div></aside></div>`;
 $('#home-search').addEventListener('input',debounce(async e=>{const term=e.target.value;const target=$('#home-search-results');if(!target)return;if(!term.trim()){target.innerHTML='';return}const qs=searchQuestions(await getAll(),term).slice(0,8);target.innerHTML=`<div class="panel" style="margin-bottom:22px"><h2>Search results</h2>${qs.length?qs.map(q=>`<a class="search-hit" href="#/question/${q.id}">${esc(q.question)}<small>${esc(q.language)} · ${esc(q.topic)}</small></a>`).join(''):'<p class="muted">No matching questions. Try another topic.</p>'}</div>`}));}
function explore(){main.innerHTML=`${pageHead('Follow your curiosity.','Every collection, ready when you are. Real questions. No filler.','','EXPLORE THE LIBRARY')}<div class="toolbar">${searchBox('explore-search','Search collections or concepts…')}<select id="group-filter" aria-label="Collection category"><option value="all">All categories</option>${[...new Set(catalog.map(c=>c.group))].map(g=>`<option>${g}</option>`).join('')}</select><select id="level-filter" aria-label="Available difficulty"><option value="all">Every difficulty</option>${['Easy','Medium','Hard','Expert'].map(g=>`<option>${g}</option>`).join('')}</select></div><div class="section-head"><small id="collection-count">${catalog.length} collections · ${total} questions</small><small>Stored locally as you practice</small></div><div id="explore-grid" class="collection-grid wide-grid">${catalog.map(collectionCard).join('')}</div>`;const filter=()=>{let list=searchCollections(catalog,$('#explore-search').value).filter(c=>($('#group-filter').value==='all'||c.group===$('#group-filter').value)&&($('#level-filter').value==='all'||c.difficulties.includes($('#level-filter').value)));$('#collection-count').textContent=`${list.length} collections · ${list.reduce((n,c)=>n+c.count,0)} questions`;$('#explore-grid').innerHTML=list.length?list.map(collectionCard).join(''):'<p class="muted">No matching collections.</p>'};$('#explore-search').addEventListener('input',debounce(filter));$('#group-filter').onchange=filter;$('#level-filter').onchange=filter;}
function selectField(name,label,options,value){return `<label class="field">${label}<select name="${name}">${options.map(([v,t])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(t)}</option>`).join('')}</select></label>`}
function toggle(name,label,desc,checked){return `<label class="toggle-row"><div>${label}<small>${desc}</small></div><input type="checkbox" name="${name}" ${checked?'checked':''}></label>`}
async function configuration(bank){const params=new URLSearchParams(location.hash.split('?')[1]||'');config={bank:catalog.some(c=>c.id===bank)?bank:'all',topics:[],difficulty:params.get('difficulty')||state.settings.difficulty,length:state.settings.length,format:params.get('format')||'all',pool:params.get('pool')||'all',timed:params.has('timed'),shuffleQuestions:true,shuffleAnswers:true};
 main.innerHTML=`${pageHead('Make this session yours.','A thoughtful setup. A focused practice.','','QUIZ CONFIGURATION')}<div class="config-layout"><form id="config-form" class="panel"><div class="form-grid">${selectField('bank','Collection',[['all','All collections'],...catalog.map(c=>[c.id,c.title])],config.bank)}${selectField('difficulty','Difficulty',['Mixed','Easy','Medium','Hard','Expert'].map(d=>[d,d]),config.difficulty)}<div class="field full"><span>Topics <small>· leave empty for all</small></span><div id="topic-options" class="topic-options"></div></div><label class="field">Number of questions<input type="number" name="length" min="1" max="100" required value="${config.length}"></label>${selectField('format','Question format',[['all','Mixed formats'],...Object.entries(formatNames)],config.format)}${selectField('pool','Question history',[['all','All questions'],['new','Not attempted yet'],['attempted','Previously attempted'],['incorrect','Previously incorrect']],config.pool)}${selectField('timed','Session timing',[['false','Untimed · your own pace'],['true','Timed · 60 seconds per question']],String(config.timed))}</div>${toggle('shuffleQuestions','Shuffle question order','A fresh order for each session.',config.shuffleQuestions)}${toggle('shuffleAnswers','Shuffle answer options','Focus on the answer, rather than its position.',config.shuffleAnswers)}<div class="button-row" style="margin-top:20px"><button type="button" class="btn" data-action="save-config">Save configuration</button><button type="button" class="btn subtle" data-action="preset">Quick practice · 5 questions</button></div></form><aside class="panel config-summary"><div class="eyebrow">YOUR SESSION</div><div id="matching-summary" role="status"><p class="summary-copy">Loading question bank…</p></div><div class="stack"><button class="btn primary" id="start-quiz" data-action="start" disabled>Start quiz ${icon('arrow')}</button>${state.session?'<a class="btn" href="#/quiz">Resume current session</a>':''}</div><p class="summary-copy" style="font-size:10px;margin-top:15px">Answers stay hidden until you submit. Pause anytime; your place is saved on this device.</p><div id="saved-configs"></div></aside></div>`;
 const update=async rebuild=>{const form=$('#config-form');if(!form)return;const f=new FormData(form);config={bank:f.get('bank'),topics:rebuild?[]:f.getAll('topic'),difficulty:f.get('difficulty'),length:Math.max(1,Math.min(100,Number(f.get('length'))||1)),format:f.get('format'),pool:f.get('pool'),timed:f.get('timed')==='true',shuffleQuestions:f.has('shuffleQuestions'),shuffleAnswers:f.has('shuffleAnswers')};const requestedBank=config.bank;try{currentQuestions=await loadQuestions(requestedBank);if(!$('#config-form')||config.bank!==requestedBank)return;if(rebuild){$('#topic-options').innerHTML=[...new Set(currentQuestions.map(q=>q.topic))].sort().map(t=>`<label><input type="checkbox" name="topic" value="${esc(t)}">${esc(t)}</label>`).join('')}matching=filterQuestions(currentQuestions,config,state.questions);$('#matching-summary').innerHTML=`<div class="match-number">${matching.length}</div><p class="summary-copy">matching questions</p><p class="summary-copy" style="font-size:10px">Available formats: ${[...new Set(currentQuestions.map(q=>formatNames[q.format]))].map(esc).join(' · ')}</p><p class="summary-copy">${matching.length<config.length?`You asked for ${config.length}; ${matching.length} are available. Start with all ${matching.length}.`:`Your session will include ${config.length} questions.`}${config.timed?`<br>Time limit: ${Math.min(config.length,matching.length)} minutes.`:''}</p>`;$('#start-quiz').disabled=!matching.length;$('#start-quiz').innerHTML=`Start ${Math.min(config.length,matching.length)} questions ${icon('arrow')}`;const meta=catalog.find(c=>c.id===config.bank);if(meta){state.recent=[meta.id,...state.recent.filter(id=>id!==meta.id)].slice(0,8);save()}}catch(e){$('#matching-summary').textContent='Could not load this collection. Reconnect and try again.';toast(e.message)}};
 $('#config-form').onchange=e=>update(e.target.name==='bank');$('#config-form').onsubmit=e=>e.preventDefault();$('#config-form [name=length]').oninput=()=>update(false);window.updateConfig=update;
 $('#saved-configs').innerHTML=state.configs.length?`<div class="eyebrow" style="margin-top:25px">SAVED SETUPS</div>${state.configs.map((c,i)=>`<button class="search-hit" style="width:100%;text-align:left" data-saved-config="${i}">${esc(catalog.find(x=>x.id===c.bank)?.title||'Mixed collections')} · ${c.length} questions<small>${esc(c.difficulty)} · ${esc(c.pool)}</small></button>`).join('')}`:'';await update(true);if(params.has('topic')){const wanted=params.get('topic');$('#topic-options').querySelectorAll('input').forEach(el=>el.checked=el.value===wanted);await update(false)}enhanceSelects(main);
}
async function startSession(list=matching,cfg=config){if(state.session&&!await askConfirm('Replace your paused session with this new quiz?'))return;state.session=createSession(list,cfg);await save();navigate('/quiz')}
function getSessionQuestions(s){return s.ids.map(id=>all.find(q=>q.id===id)).filter(Boolean)}
async function quiz(){if(!state.session){navigate('/');return}const s=state.session;await loadForSession(s);if(getSessionQuestions(s).length!==s.ids.length){toast('This saved session references unavailable questions.');navigate('/settings');return}selection=[];hint=false;drawQuestion();lastTick=Date.now();clearInterval(timer);timer=setInterval(()=>{if(route()!=='/quiz'||!state.session||document.hidden){lastTick=Date.now();return;}const now=Date.now();state.session.elapsed+=Math.max(0,Math.min(now-lastTick,3000));lastTick=now;const remaining=state.session.ids.length*60000-state.session.elapsed;const el=$('#quiz-timer');if(el)el.textContent=duration(state.session.config.timed?remaining:state.session.elapsed);if(state.session.config.timed&&remaining<=0)finishSession(true);else if(Math.floor(state.session.elapsed/1000)%5===0)save()},1000)}
function drawQuestion(){const s=state.session;if(!s)return;const q=all.find(q=>q.id===s.ids[s.index]),response=s.responses[q.id],meta=catalog.find(c=>c.id===q.language),selected=response?.selected||selection;const order=s.optionOrders[q.id]||q.options.map(o=>o.id);main.innerHTML=`<div class="quiz-wrap"><div class="quiz-head"><button class="icon-btn" data-action="pause" aria-label="Pause quiz">${icon('back')}</button><div class="title"><h2>${esc(s.config.bank==='all'?'Mixed practice':meta?.title||'Practice')}</h2><p>Question ${String(s.index+1).padStart(2,'0')} / ${String(s.ids.length).padStart(2,'0')}</p></div><span class="pill">${icon('clock')}<span id="quiz-timer">${duration(s.config.timed?s.ids.length*60000-s.elapsed:s.elapsed)}</span></span><button class="icon-btn ${state.bookmarks.includes(q.id)?'bookmarked':''}" data-bookmark="${q.id}" aria-label="${state.bookmarks.includes(q.id)?'Remove bookmark':'Bookmark question'}" aria-pressed="${state.bookmarks.includes(q.id)}">${icon('bookmark')}</button></div><div class="progress" role="progressbar" aria-label="Quiz progress" aria-valuemin="0" aria-valuemax="${s.ids.length}" aria-valuenow="${Object.keys(s.responses).length}"><div style="width:${Object.keys(s.responses).length/s.ids.length*100}%"></div></div><div class="question-meta"><span class="tag">${esc(meta?.title||q.language)}</span><span class="tag ${q.difficulty.toLowerCase()}">${q.difficulty}</span><span>${esc(q.topic)}</span><span>·</span><span>${formatNames[q.format]}</span></div><h1 class="question-title">${esc(q.question)}</h1>${q.format==='multiple'?'<p class="question-subtitle">Select all correct answers. Exact selection is required.</p>':q.format==='comparison'?'<p class="question-subtitle">Read both labeled snippets before choosing.</p>':q.format==='complete'?'<p class="question-subtitle">Choose the replacement for /* ? */.</p>':''}${codeBlock(q.code,meta?.title||q.language,state.settings)}<div class="options" role="group" aria-label="Answer options">${order.map((id,i)=>{const o=q.options.find(x=>x.id===id);const isSelected=selected.includes(id),correct=response&&q.answers.includes(id),incorrect=response&&isSelected&&!q.answers.includes(id);return `<button class="option ${isSelected?'selected':''} ${correct?'correct':''} ${incorrect?'incorrect':''}" data-option="${id}" aria-pressed="${isSelected}" ${response?'disabled':''}><span class="option-id">${correct?'✓':incorrect?'×':String.fromCharCode(65+i)}</span><span class="option-text">${esc(o.text)}</span>${response?(correct?icon('check'):incorrect?icon('close'):''):''}</button>`}).join('')}</div>${hint&&!response?`<div class="hint">${icon('bulb')} ${esc(q.hint)}</div>`:''}${response?`<div class="feedback ${response.correct?'':'bad'}" role="status"><strong>${icon(response.correct?'check':'close')} ${response.correct?'Correct answer':'Not quite. Here’s why.'}</strong><p>${esc(q.explanation)}</p>${q.explanationCode?codeBlock(q.explanationCode,q.language,state.settings):''}</div>`:''}<div class="quiz-actions"><button class="btn subtle" data-action="previous" ${s.index===0?'disabled':''}>${icon('back')} Previous</button><div class="right">${!response?`<button class="btn subtle" data-action="hint" aria-label="Show hint">${icon('bulb')} Hint</button><button class="btn primary" data-action="submit" ${!selection.length?'disabled':''}>Submit answer</button>`:`<button class="btn primary" data-action="next">${s.index===s.ids.length-1?'Finish quiz':'Next question'} ${icon('arrow')}</button>`}</div></div><div class="button-row" style="justify-content:space-between"><button class="text-btn" data-action="pause">Pause & save</button><button class="text-btn" data-action="finish-early">Finish session early</button></div></div>`}
async function finishSession(timed=false){if(!state.session)return;clearInterval(timer);const s=state.session;s.finishedAt=Date.now();state.history.unshift(structuredClone(s));state.session=null;await save();if(timed)toast('Time is up. Your submitted answers have been saved.');navigate('/results/'+s.id)}
function reviewCard(q,response=null,showAnswer=false){const p=state.questions[q.id];return `<details class="review"><summary>${icon(showAnswer?(response?response.correct?'check':'close':'pause'):'code')}<span>${esc(q.question)}</span><span class="tag" style="flex:0;white-space:nowrap">${showAnswer?response?response.correct?'Correct':'Incorrect':'Unanswered':esc(q.language)}</span></summary><div class="review-content"><p>${esc(q.language)} · ${esc(q.topic)} · ${q.difficulty}</p>${codeBlock(q.code,q.language,state.settings)}${showAnswer?`<p>Your answer: ${response?esc(response.selected.map(id=>q.options.find(o=>o.id===id)?.text||id).join(' · ')):'Not submitted'}</p><p class="good">Correct answer: ${esc(q.answers.map(id=>q.options.find(o=>o.id===id).text).join(' · '))}</p><p>${esc(q.explanation)}</p>`:`<div class="options">${q.options.map((o,i)=>`<div class="option"><span class="option-id">${String.fromCharCode(65+i)}</span><span class="option-text">${esc(o.text)}</span></div>`).join('')}</div><a href="#/practice/${q.id}" class="btn primary">Practice this question ${icon('arrow')}</a>`}<p class="muted">${p?`${p.attempts} attempts · ${p.correct} correct · ${p.incorrect} incorrect · Last attempt ${date(p.lastAt)}`:'Not attempted yet'}</p><button class="btn ${state.bookmarks.includes(q.id)?'bookmarked':''}" data-bookmark="${q.id}" aria-pressed="${state.bookmarks.includes(q.id)}">${icon('bookmark')}${state.bookmarks.includes(q.id)?'Bookmarked':'Bookmark question'}</button></div></details>`}
async function results(id){const s=state.history.find(h=>h.id===id);if(s)await loadForSession(s);if(!s){main.innerHTML=empty('history','Session not found','This session may have been cleared from this device.','/history','View history');return}viewedResult=s;const r=score(s);main.innerHTML=`${pageHead('A clearer picture.','Review the reasoning. Keep what you learned.','','SESSION COMPLETE')}<div class="panel" style="display:flex;justify-content:space-between;align-items:center;gap:20px"><div><div class="eyebrow">${esc(catalog.find(c=>c.id===s.config.bank)?.title||'MIXED PRACTICE')}</div><h2 style="font-size:34px;margin-top:7px">${r.score}% <small>score</small></h2><small>${r.accuracy}% accuracy on submitted answers · ${duration(s.elapsed)} active time</small></div>${icon('chart')}</div><div class="result-stats"><div class="result-stat"><strong>${r.total}</strong><small>Total questions</small></div><div class="result-stat"><strong class="good">${r.correct}</strong><small>Correct answers</small></div><div class="result-stat"><strong class="bad-text">${r.incorrect}</strong><small>Incorrect answers</small></div><div class="result-stat"><strong>${r.unanswered}</strong><small>Unanswered</small></div></div><div class="button-row"><button class="btn primary" data-action="retry">Retry quiz ${icon('refresh')}</button><button class="btn" data-action="practice-incorrect" ${r.incorrect?'':'disabled'}>Practice incorrect answers</button><a class="btn subtle" href="#/">Back to workspace</a></div><section class="section"><div class="section-head"><h2>Question-by-question review</h2><small>${date(s.finishedAt)}</small></div>${getSessionQuestions(s).map(q=>reviewCard(q,s.responses[q.id],true)).join('')}</section>`}
async function bookmarks(){await getAll();const list=all.filter(q=>state.bookmarks.includes(q.id));main.innerHTML=`${pageHead('Worth another thought.','Your saved questions, all in one place.','','BOOKMARKS')}${list.length?`<div class="section-head"><small>${list.length} saved questions</small><button class="btn primary" data-action="practice-bookmarks">Practice bookmarks ${icon('arrow')}</button></div>${list.map(q=>reviewCard(q)).join('')}`:empty('bookmark','Keep a good question close.','Tap the bookmark in any quiz to save a question here.','/explore')}`}
function history(){main.innerHTML=`${pageHead('A record of your thinking.','Every completed session. Every answer worth revisiting.','','QUIZ HISTORY')}${state.history.length?`<div class="history-list">${state.history.map(h=>`<a class="history-item" href="#/results/${esc(h.id)}">${icon('layers')}<div><strong>${esc(catalog.find(c=>c.id===h.config.bank)?.title||'Mixed practice')}</strong><p>${h.ids.length} questions · ${duration(h.elapsed)} · ${date(h.finishedAt)}</p></div><strong>${score(h).score}%</strong>${icon('arrow')}</a>`).join('')}</div>`:empty('history','Your next session starts here.','Completed quizzes and their explanations will appear here.','/config/all','Start a quiz')}`}
function settings(){const s=state.settings,stats=statistics(state);main.innerHTML=`${pageHead('A workspace that fits you.','Small adjustments. A more comfortable practice.','','SETTINGS')}<div class="settings-layout"><section class="panel"><h2>Appearance & reading</h2><form id="settings-form"><div class="form-grid" style="margin-top:20px">${selectField('theme','Theme',[['dark','Midnight'],['dim','Dim slate'],['light','Paper light']],s.theme)}${selectField('accent','Accent color',[['#a07bed','Violet'],['#b7a0f8','Lavender'],['#739eea','Blue'],['#70bba5','Sage'],['#e7b478','Warm amber']],s.accent)}${selectField('codeSize','Code font size',[11,12,13,14,15,16,18,20].map(n=>[String(n),n+' px']),String(s.codeSize))}${selectField('textSize','Interface text size',[12,13,14,15,16,17,18].map(n=>[String(n),n+' px']),String(s.textSize))}${selectField('length','Default quiz length',[1,5,10,15,20,30,50,100].map(n=>[String(n),n+' questions']),String(s.length))}${selectField('difficulty','Default difficulty',['Mixed','Easy','Medium','Hard','Expert'].map(d=>[d,d]),s.difficulty)}</div>${toggle('lineNumbers','Code line numbers','A little structure for multiline snippets.',s.lineNumbers)}${toggle('reducedMotion','Reduce motion','Keep interface transitions to a minimum.',s.reducedMotion)}${toggle('sound','Quiet answer sounds','A short tone after submitting an answer.',s.sound)}<small style="display:block;margin-top:16px">Changes save automatically on this device.</small></form></section><section class="panel"><h2>Your local data</h2><p class="summary-copy">No account, cloud sync or remote analytics. Export a backup before clearing browser data or moving devices.</p><div class="data-grid"><div><strong>${stats.attempts}</strong><small>Total attempts</small></div><div><strong>${stats.unique}</strong><small>Unique questions</small></div><div><strong>${stats.sessions}</strong><small>Completed sessions</small></div><div><strong>${stats.correct}</strong><small>Correct attempts</small></div><div><strong>${stats.incorrect}</strong><small>Incorrect attempts</small></div><div><strong>${stats.unanswered}</strong><small>Unanswered in sessions</small></div><div><strong>${state.bookmarks.length}</strong><small>Bookmarks</small></div></div><div class="button-row"><button class="btn" data-action="export">${icon('download')} Export activity</button><button class="btn" data-action="import">${icon('upload')} Import backup</button><input type="file" id="import-file" accept="application/json,.json" hidden></div><div class="toggle-row"><div>Clear quiz history<small>Removes completed sessions; keeps question statistics and bookmarks.</small></div><button class="btn danger" data-action="clear-history">Clear</button></div><div class="toggle-row"><div>Reset all local data<small>Removes progress, bookmarks, configurations and preferences.</small></div><button class="btn danger" data-action="reset">Reset</button></div></section><section class="panel"><h2>Offline & installation</h2><p class="summary-copy" id="offline-details">Core files and question banks cache after the first successful load. Wait for “Offline ready” before relying on airplane mode.</p><div class="button-row"><button class="btn" data-action="offline">Check offline availability</button><button class="btn" id="install-button" data-action="install">Install app</button></div><p class="summary-copy" style="margin-bottom:0">CodeQuest 2.0.0 · ${total} questions · ${catalog.length} modular collections.<br>Built with HTML, CSS and vanilla JavaScript.</p></section></div>`;
 $('#settings-form').onchange=async()=>{const f=new FormData($('#settings-form'));state.settings={theme:f.get('theme'),accent:f.get('accent'),codeSize:Number(f.get('codeSize')),textSize:Number(f.get('textSize')),length:Number(f.get('length')),difficulty:f.get('difficulty'),lineNumbers:f.has('lineNumbers'),sound:f.has('sound'),reducedMotion:f.has('reducedMotion')};applySettings(state.settings);if(await save())toast('Preferences saved')};$('#settings-form').onsubmit=e=>e.preventDefault();$('#import-file').onchange=importFile;enhanceSelects(main);}
async function importFile(e){const file=e.target.files[0];if(!file)return;try{if(file.size>10*1024*1024)throw new Error('Choose a backup under 10 MB.');await getAll();const next=validateData(JSON.parse(await file.text()),new Set(all.map(q=>q.id)));for(const s of [...next.history,...(next.session?[next.session]:[])]){for(const id of s.ids){const q=all.find(x=>x.id===id),order=s.optionOrders[id];if(order.length!==q.options.length||order.some(a=>!q.options.some(o=>o.id===a)))throw new Error('Backup contains invalid option ordering.')}for(const [id,r] of Object.entries(s.responses)){const q=all.find(x=>x.id===id);if(r.selected.some(a=>!q.options.some(o=>o.id===a))||r.correct!==(r.selected.length===q.answers.length&&r.selected.every(a=>q.answers.includes(a))))throw new Error('Backup contains invalid answer records.')}}if(!await askConfirm('Replace your current local activity and preferences with this backup?'))return;await persist(next);state=next;applySettings(state.settings);await render();toast('Activity imported successfully')}catch(e){toast('Import failed: '+e.message)}}
let installPrompt=null;window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e});
async function render(){const token=++renderToken;closeDialog();clearInterval(timer);document.body.classList.toggle('quiz-mode',route()==='/quiz');chrome();window.scrollTo(0,0);const p=route();try{if(p==='/')home();else if(p==='/explore')explore();else if(p==='/learn')main.innerHTML=learningHTML(catalog,state);else if(p.startsWith('/learn/')){const bank=catalog.find(c=>c.id===p.split('/')[2]);if(bank)main.innerHTML=learningHTML(catalog,state,bank,await loadQuestions(bank.id));else navigate('/learn')}else if(p.startsWith('/config/'))await configuration(p.split('/')[2]);else if(p==='/quiz')await quiz();else if(p.startsWith('/results/'))await results(p.split('/')[2]);else if(p==='/bookmarks')await bookmarks();else if(p==='/history')history();else if(p==='/settings')settings();else if(p.startsWith('/question/')){await getAll();const q=all.find(q=>q.id===p.split('/')[2]);main.innerHTML=pageHead('Take a closer look.','Explore the question, then practice to check your understanding.','','QUESTION LIBRARY')+(q?reviewCard(q):empty('search','Question not found','Try another collection.','/explore'));main.querySelector('details')?.setAttribute('open','')}else if(p.startsWith('/practice/')){await getAll();const q=all.find(q=>q.id===p.split('/')[2]);if(q)await startSession([q],{bank:q.language,topics:[],difficulty:'Mixed',length:1,format:'all',pool:'all',timed:false,shuffleQuestions:false,shuffleAnswers:false});else navigate('/explore')}else navigate('/');if(token!==renderToken)return;enhanceSelects(main);}catch(e){main.innerHTML=empty('wifi','Could not open this screen.','A required question bank or file is unavailable. Reconnect and reload to try again.','/','Back home');toast(e.message)}}
window.addEventListener('hashchange',render);
window.addEventListener('storage-warning',e=>toast(e.detail));
window.addEventListener('offline',()=>{chrome();toast('You’re offline. Cached content stays available.')});window.addEventListener('online',chrome);
window.addEventListener('pagehide',()=>save());document.addEventListener('visibilitychange',()=>{if(document.hidden)save();else lastTick=Date.now()});
document.querySelector('.skip').addEventListener('click',e=>{e.preventDefault();main.focus();main.scrollIntoView()});
document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName)){const search=main.querySelector('input[type=search]');if(search){e.preventDefault();search.focus()}}});
document.addEventListener('click',async e=>{const btn=e.target.closest('[data-action],[data-bank],[data-home-group],[data-option],[data-bookmark],[data-saved-config]');if(!btn||btn.disabled)return;try{
 if(btn.dataset.bank){navigate('/config/'+btn.dataset.bank);return}
 if(btn.dataset.homeGroup){$('#home-chips').querySelectorAll('button').forEach(b=>b.classList.toggle('active',b===btn));const group=btn.dataset.homeGroup;$('#home-collections').innerHTML=(group==='Popular'?catalog.filter(c=>['javascript','python','java','cpp','sql','typescript'].includes(c.id)):catalog.filter(c=>c.group===group)).slice(0,6).map(collectionCard).join('');return}
 if(btn.dataset.option){const s=state.session,q=all.find(q=>q.id===s.ids[s.index]);if(s.responses[q.id])return;const id=btn.dataset.option;selection=q.format==='multiple'?(selection.includes(id)?selection.filter(x=>x!==id):[...selection,id]):[id];main.querySelectorAll('[data-option]').forEach(b=>{const selected=selection.includes(b.dataset.option);b.classList.toggle('selected',selected);b.setAttribute('aria-pressed',String(selected))});$('[data-action=submit]').disabled=!selection.length;return}
 if(btn.dataset.bookmark){const id=btn.dataset.bookmark;state.bookmarks=state.bookmarks.includes(id)?state.bookmarks.filter(x=>x!==id):[...state.bookmarks,id];await save();btn.classList.toggle('bookmarked',state.bookmarks.includes(id));btn.setAttribute('aria-pressed',String(state.bookmarks.includes(id)));btn.setAttribute('aria-label',state.bookmarks.includes(id)?'Remove bookmark':'Bookmark question');if(btn.textContent.trim())btn.innerHTML=icon('bookmark')+(state.bookmarks.includes(id)?'Bookmarked':'Bookmark question');chrome();toast(state.bookmarks.includes(id)?'Question bookmarked':'Bookmark removed');return}
 if(btn.dataset.savedConfig!==undefined){const c=state.configs[Number(btn.dataset.savedConfig)];const form=$('#config-form');for(const [k,v] of Object.entries(c)){const field=form.elements[k];if(field&&k!=='topics'){if(field.type==='checkbox')field.checked=v;else field.value=String(v)}}await window.updateConfig(true);form.querySelectorAll('[name=topic]').forEach(el=>el.checked=c.topics.includes(el.value));await window.updateConfig(false);$('#config-form').querySelectorAll('select').forEach(el=>el.dispatchEvent(new Event('change')));toast('Saved configuration loaded');return}
 const action=btn.dataset.action;
 if(action==='expand-code'){const block=btn.closest('.code-block');block.classList.toggle('expanded');btn.textContent=block.classList.contains('expanded')?'Compact':'Expand'}
 else if(action==='copy-code'){const text=btn.closest('.code-block').querySelector('template').content.textContent;try{await navigator.clipboard.writeText(text);toast('Code copied')}catch{toast('Clipboard access unavailable in this browser. Select the code to copy.')}}
 else if(action==='start')await startSession();
 else if(action==='preset'){const f=$('#config-form');f.elements.namedItem('length').value='5';f.elements.difficulty.value='Mixed';f.elements.format.value='all';f.elements.pool.value='all';await window.updateConfig(false);$('#config-form').querySelectorAll('select').forEach(el=>el.dispatchEvent(new Event('change')))}
 else if(action==='save-config'){if(state.configs.length>=12)state.configs.shift();state.configs.push(structuredClone(config));await save();toast('Configuration saved. Find it here next time.')}
 else if(action==='submit'){const s=state.session,q=all.find(q=>q.id===s.ids[s.index]);if(recordAnswer(state,s,q,selection)){await save();playFeedback(state.settings.sound,s.responses[q.id].correct);drawQuestion()}}
 else if(action==='next'){if(state.session.index===state.session.ids.length-1)await finishSession();else{state.session.index++;selection=[];hint=false;await save();drawQuestion();window.scrollTo(0,0)}}
 else if(action==='previous'){state.session.index=Math.max(0,state.session.index-1);selection=[];hint=false;await save();drawQuestion()}
 else if(action==='hint'){hint=!hint;drawQuestion()}
 else if(action==='pause'){await save();navigate('/')}
 else if(action==='finish-early'){if(await askConfirm('Finish now? Questions without submitted answers will be marked unanswered.'))await finishSession()}
 else if(action==='retry')await startSession(getSessionQuestions(viewedResult),{...viewedResult.config,length:viewedResult.ids.length});
 else if(action==='practice-incorrect'){const qs=getSessionQuestions(viewedResult).filter(q=>viewedResult.responses[q.id]?.correct===false);await startSession(qs,{...viewedResult.config,length:qs.length,pool:'incorrect'})}
 else if(action==='practice-bookmarks'){const qs=(await getAll()).filter(q=>state.bookmarks.includes(q.id));await startSession(qs,{bank:'all',topics:[],difficulty:'Mixed',length:qs.length,format:'all',pool:'all',timed:false,shuffleQuestions:true,shuffleAnswers:true})}
 else if(action==='export'){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='codequest-activity-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Activity export downloaded')}
 else if(action==='import')$('#import-file').click();
 else if(action==='clear-history'){if(await askConfirm('Clear completed quiz history? Question statistics and bookmarks will stay.')){state.history=[];await save();settings();toast('Quiz history cleared')}}
 else if(action==='reset'){if(await askConfirm('Permanently reset all CodeQuest activity on this device? Export a backup first if you want to keep it.')){state=defaults();await save();applySettings(state.settings);chrome();settings();toast('Local data reset')}}
 else if(action==='offline'){const keys=await caches.keys(),name=keys.find(k=>k.startsWith('codequest-'));if(!name){$('#offline-details').textContent='Offline cache is not ready. Load this app over HTTPS or localhost and try again.';return}const cache=await caches.open(name),expected=['index.html','js/app.js',...catalog.map(c=>'data/'+c.id+'.js')],checks=await Promise.all(expected.map(p=>cache.match(new URL(p,location.href).href)));$('#offline-details').textContent=checks.every(Boolean)?`Offline ready: app shell and all ${catalog.length} question banks are cached on this device.`:'Some files are not cached yet. Stay online, reload once, and check again.'}
 else if(action==='install'){if(installPrompt){await installPrompt.prompt();installPrompt=null}else toast('On Android Chrome: open the browser menu, then choose “Install app” or “Add to Home screen”.')}
 }catch(error){toast(error.message)}});
await render();
if('serviceWorker' in navigator){navigator.serviceWorker.register('./service-worker.js').catch(()=>toast('Offline setup unavailable. You can still practice online.'));navigator.serviceWorker.addEventListener('message',e=>{if(e.data?.type==='offline-ready')toast('Offline ready. All question banks are cached.')})}
